-- ========================================================
-- SCRIPT DE MIGRACIÓN DE PRODUCTOS - MUSAMÍ STORE
-- Copia y pega este script en el Editor SQL de Supabase
-- ========================================================

-- 1. Crear tabla de productos
CREATE TABLE IF NOT EXISTS public.products (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    brand TEXT,
    price NUMERIC,
    images JSONB,
    stock INTEGER,
    category TEXT NOT NULL,
    subcategory TEXT,
    variants JSONB,
    description TEXT
);

-- 2. Habilitar RLS (Seguridad a Nivel de Fila)
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;

-- 3. Eliminar políticas previas si existen para evitar duplicados
DROP POLICY IF EXISTS "Allow public read access" ON public.products;
DROP POLICY IF EXISTS "Allow authenticated insert" ON public.products;
DROP POLICY IF EXISTS "Allow authenticated update" ON public.products;
DROP POLICY IF EXISTS "Allow authenticated delete" ON public.products;

-- 4. Crear Políticas de Seguridad
CREATE POLICY "Allow public read access" ON public.products FOR SELECT USING (true);
CREATE POLICY "Allow authenticated insert" ON public.products FOR INSERT WITH CHECK (auth.role() = 'authenticated');
CREATE POLICY "Allow authenticated update" ON public.products FOR UPDATE USING (auth.role() = 'authenticated') WITH CHECK (auth.role() = 'authenticated');
CREATE POLICY "Allow authenticated delete" ON public.products FOR DELETE USING (auth.role() = 'authenticated');

-- 5. Crear Función Segura para Rebajar Stock
CREATE OR REPLACE FUNCTION public.decrement_stock(product_id TEXT, qty INT, variant_key TEXT DEFAULT NULL)
RETURNS VOID AS $$
BEGIN
    IF variant_key IS NULL OR variant_key = '' THEN
        UPDATE public.products 
        SET stock = GREATEST(0, stock - qty)
        WHERE id = product_id;
    ELSE
        UPDATE public.products 
        SET variants = jsonb_set(
            variants, 
            ARRAY[variant_key, 'stock'], 
            to_jsonb(GREATEST(0, (variants->variant_key->>'stock')::int - qty))
        )
        WHERE id = product_id;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

GRANT EXECUTE ON FUNCTION public.decrement_stock TO anon;
GRANT EXECUTE ON FUNCTION public.decrement_stock TO authenticated;

-- 6. Limpiar datos anteriores (opcional, para reinicio limpio)
TRUNCATE TABLE public.products;

